# Check structure of search results
r = await CONTEXT.search("[grade]")
print(type(r))
if isinstance(r, list):
    print(f"len={len(r)}")
    for i, m in enumerate(r):
        print(f"  [{i}] type={type(m)}, keys={m.keys() if isinstance(m, dict) else 'N/A'}")
        if isinstance(m, dict):
            print(f"      offset={m.get('offset')}, snippet={m.get('snippet', '')[:200]}")
elif isinstance(r, dict):
    print(f"keys={r.keys()}")
    print(str(r)[:500])
